		if (n == 1) {
			final Entry top = new Entry(s.readInt());
			top.pred(pred);
			top.succ(succ);
			top.black(true);
			return top;
		}
		if (n == 2) {
			/* We handle separately this case so that recursion will
				 *always* be on nonempty subtrees. */
			final Entry top = new Entry(s.readInt());
			top.black(true);
			top.right(new Entry(s.readInt()));
			top.right.pred(top);
			top.pred(pred);
			top.right.succ(succ);
			return top;
