		setActualComparator();
		allocatePaths();
		if (count != 0) {
			tree = readTree(s, count, null, null);
			Entry e;
			e = tree;
			while (e.left() != null) e = e.left();
			firstEntry = e;
			e = tree;
			while (e.right() != null) e = e.right();
			lastEntry = e;
